/// <summary>
/// CB 797 send PE pricing Data contract class as a response for service <c>METSendPEPricingResponseContract</c>
/// </summary>
[DataContractAttribute]
class METSendPEPricingResponseContract extends METBaseResponseContract
{
}

Method.Source:
/// <summary>
/// Contruct a new Response contract
/// </summary>
/// <param name = "_result">Result of the PE Pricing Value</param>
/// <param name = "_message">Message Result</param>
/// <returns>new contract</returns>
public static METSendPEPricingResponseContract newFromParameters(METProcessingStatus _result, Description255 _message)
{
    METSendPEPricingResponseContract response = new METSendPEPricingResponseContract();

    response.parmResult(enum2Symbol(enumNum(METProcessingStatus), enum2int(_result)));
    response.parmMessage(_message);

    return response;
}
